parameters.jsCode:
const aiResponse = $input.first().json.message?.content || $input.first().json.output || '';

try {
  // Extract JSON from response
  const jsonMatch = aiResponse.match(/\{[\s\S]*\}/);
  if (!jsonMatch) {
    return [{
      json: {
        intent: 'Other',
        courseInterest: '',
        interestLevel: 'Low',
        qualified: false,
        reason: 'Could not parse AI response'
      }
    }];
  }

  const parsed = JSON.parse(jsonMatch[0]);

  return [{
    json: {
      ...parsed,
      studentName: $('Extract WhatsApp Data').first().json.studentName,
      phoneNumber: $('Extract WhatsApp Data').first().json.phoneNumber,
      studentEmail: $('Extract WhatsApp Data').first().json.studentEmail,
      messageText: $('Extract WhatsApp Data').first().json.messageText,
      timestamp: $('Extract WhatsApp Data').first().json.timestamp
    }
  }];
} catch (error) {
  return [{
    json: {
      intent: 'Other',
      courseInterest: '',
      interestLevel: 'Low',
      qualified: false,
      reason: 'Error parsing response: ' + error.message,
      studentName: $('Extract WhatsApp Data').first().json.studentName,
      phoneNumber: $('Extract WhatsApp Data').first().json.phoneNumber,
      studentEmail: $('Extract WhatsApp Data').first().json.studentEmail,
      messageText: $('Extract WhatsApp Data').first().json.messageText,
      timestamp: $('Extract WhatsApp Data').first().json.timestamp
    }
  }];
}

// Generate 6-digit OTP
const otp = Math.floor(100000 + Math.random() * 900000).toString();

// Calculate expiry time
const expiryMinutes = $('Workflow Configuration').first().json.otpExpiryMinutes || 10;
const expiryTime = new Date(Date.now() + expiryMinutes * 60000).toISOString();

return [{
  json: {
    ...($input.first().json),
    otp: otp,
    otpExpiry: expiryTime,
    otpGenerated: new Date().toISOString()
  }
}];

